/* Facility Compliance Interface — prototype rules engine + wizard UI.
 * All reference data lives in data/*.json (generated by scripts/build_data.py
 * from Facility_Compliance_Parameter_Schema.xlsx). This file never edits
 * that data — it only renders it and evaluates entered values against it.
 */

// ---------------------------------------------------------------------
// Constants not carried in the data files (UI-only groupings)
// ---------------------------------------------------------------------

const CATEGORY_DEFS = [
  { key: "ext_prep", label: "External Preparations", desc: "Liquids, creams, ointments, gels, dusting powders" },
  { key: "osd_production", label: "OSD Production", desc: "Commercial-scale tablets, capsules, oral powders, MDF, buccal film" },
  { key: "osd_rnd_pilot", label: "OSD R&D / Pilot Plant", desc: "Non-commercial development & pilot-scale OSD work" },
  { key: "sterile", label: "Sterile", desc: "Parenterals, ophthalmics, dry-powder reconstitution, implants" },
];

const SPECIFIC_FORMS = {
  ext_prep: ["Liquid", "Emulsion", "Suspension", "Cream", "Ointment", "Gel", "Dusting Powder"],
  osd_production: ["Tablet (Uncoated)", "Tablet (Coated)", "Tablet (Extended Release)", "Tablet (Modified Release)", "Capsule", "Oral Powder", "MDF (Mouth Dissolving Film)", "Buccal Film"],
  osd_rnd_pilot: ["Tablet (Uncoated)", "Tablet (Coated)", "Tablet (Extended Release)", "Tablet (Modified Release)", "Capsule", "Oral Powder", "MDF (Mouth Dissolving Film)", "Buccal Film"],
  sterile: ["Sterile Liquid (Vial)", "Sterile Liquid (Ampoule)", "Sterile Liquid (PFS)", "Sterile Liquid (Cartridge)", "Ophthalmic Drops", "Ophthalmic Ointment", "Dry Powder Reconstitution", "Implant"],
};

const OPTION_OVERRIDES = {
  "UTIL-001": ["Class 1", "Class 1.2.1", "Class 2"],
  "SHE-004": ["OEB 1", "OEB 2", "OEB 3", "OEB 4", "OEB 5"],
  "HVAC-001": ["Unclassified/CNC", "Grade D (ISO 8)", "Grade C (ISO 7)", "Grade B", "Grade A (ISO 5)"],
};

const GRADE_HIERARCHY = ["Unclassified/CNC", "Grade D (ISO 8)", "Grade C (ISO 7)", "Grade B", "Grade A (ISO 5)"];
const GRADE_TAG_TO_LABEL = { A: "Grade A (ISO 5)", B: "Grade B", C: "Grade C (ISO 7)", D: "Grade D (ISO 8)", Unclassified: "Unclassified/CNC", Controlled: "Unclassified/CNC", Technical: "Unclassified/CNC" };

const SEVERITY_RANK = { Critical: 4, Significant: 3, Partial: 2, Aligned: 1, Varies: 2 };
const SEVERITY_ORDER = ["Critical", "Significant", "Partial", "Aligned"];

// Parameters that are captured but never scored pass/fail (free-text / structural).
const NON_SCORED_CATEGORY_EXCLUDE = ["Classification", "Compliance Output"];

// Restrict a handful of parameters to the rooms they actually apply to
// (their schema-level applicability is broader than a single room type).
const PARAM_ROOM_FILTERS = {
  "DFS-003": (room) => /MDF|Buccal/i.test(room.name),
  "DFS-004": (room) => room.process_stage === "Filling",
  "DFS-007": (room) => /Implant/i.test(room.name),
  "SHE-003": (room) => /Granulat|Compress|Blend|Coat|Dust|Powder/i.test(room.name),
  "DFS-001": (room) => /Dust|Powder|Granulat|Blend/i.test(room.name),
  "DFS-002": (room) => /Liquid|Emulsion|Suspension|Coating/i.test(room.name),
  "HVAC-009": (room) => room.grade_tag === "A",
  "HVAC-010": (room) => room.grade_tag === "A" || room.grade_tag === "B",
  "DIM-005": (room) => /Corridor|Buffer/i.test(room.process_stage),
  "DIM-006": (room) => /Airlock|Hatch|Gowning/i.test(room.process_stage + " " + room.name),
  "FLOW-001": (room) => /Airlock|Hatch|Gowning/i.test(room.process_stage + " " + room.name),
  "FLOW-002": (room) => /Airlock|Hatch|Gowning/i.test(room.process_stage + " " + room.name),
};

// ---------------------------------------------------------------------
// State
// ---------------------------------------------------------------------

const state = {
  step: 1,
  category: null,
  devStage: null,
  specificForms: [],
  targetMarkets: ["schedule_m"],
  scaleSize: "Medium",
  batchSize: "",
  selectedRooms: [],
  facilityValues: {}, // paramId -> value
  roomValues: {}, // roomId -> { paramId -> value }
};

let DATA = null; // populated by loadData()

// ---------------------------------------------------------------------
// DOM helper
// ---------------------------------------------------------------------

function h(tag, attrs = {}, children = []) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs || {})) {
    if (v === null || v === undefined) continue;
    if (k === "class") el.className = v;
    else if (k === "html") el.innerHTML = v;
    else if (k.startsWith("on") && typeof v === "function") el.addEventListener(k.slice(2), v);
    else el.setAttribute(k, v);
  }
  (Array.isArray(children) ? children : [children]).forEach((c) => {
    if (c === null || c === undefined || c === false) return;
    el.appendChild(typeof c === "string" || typeof c === "number" ? document.createTextNode(c) : c);
  });
  return el;
}

function clear(el) {
  while (el.firstChild) el.removeChild(el.firstChild);
}

// ---------------------------------------------------------------------
// Data loading
// ---------------------------------------------------------------------

async function loadData() {
  const files = ["parameters", "rooms", "thresholds", "boolean_thresholds", "authorities", "structural_flags"];
  const results = await Promise.all(files.map((f) => fetch(`data/${f}.json`).then((r) => r.json())));
  const data = {};
  files.forEach((f, i) => (data[f] = results[i]));
  data.paramById = Object.fromEntries(data.parameters.map((p) => [p.id, p]));
  data.roomById = Object.fromEntries(data.rooms.map((r) => [r.id, r]));
  data.authorityByKey = Object.fromEntries(data.authorities.map((a) => [a.key, a]));
  return data;
}

// ---------------------------------------------------------------------
// Step 1 — Classification
// ---------------------------------------------------------------------

function renderStep1() {
  const root = document.getElementById("step-1");
  clear(root);

  const panel = h("div", { class: "panel" });
  panel.appendChild(h("h2", {}, "Step 1 — Classification"));

  panel.appendChild(h("h3", {}, "Dosage Form Category"));
  const grid = h("div", { class: "choice-grid" });
  CATEGORY_DEFS.forEach((c) => {
    const card = h(
      "button",
      {
        type: "button",
        class: "choice-card" + (state.category === c.key ? " selected" : ""),
        onclick: () => {
          state.category = c.key;
          state.specificForms = [];
          state.devStage = null;
          state.selectedRooms = [];
          renderStep1();
        },
      },
      [h("strong", {}, c.label), h("span", {}, c.desc)]
    );
    grid.appendChild(card);
  });
  panel.appendChild(grid);

  if (state.category === "osd_rnd_pilot") {
    panel.appendChild(h("h3", {}, "Facility Development Stage"));
    panel.appendChild(h("p", { class: "field-hint" }, "Schedule M has no dedicated chapter for either — this only affects the wording of the structural-gap notice in your results."));
    const devGrid = h("div", { class: "choice-grid" });
    ["R&D Lab", "Pilot Plant"].forEach((stg) => {
      devGrid.appendChild(
        h(
          "button",
          {
            type: "button",
            class: "choice-card" + (state.devStage === stg ? " selected" : ""),
            onclick: () => {
              state.devStage = stg;
              renderStep1();
            },
          },
          h("strong", {}, stg)
        )
      );
    });
    panel.appendChild(devGrid);
  }

  if (state.category) {
    panel.appendChild(h("h3", {}, "Specific Dosage Form(s)"));
    panel.appendChild(h("p", { class: "field-hint" }, "Selecting MDF, Buccal Film, or Implant will flag a Schedule M regulatory vacuum in your results."));
    const formGrid = h("div", { class: "checkbox-list" });
    SPECIFIC_FORMS[state.category].forEach((form) => {
      const id = "form-" + form.replace(/[^a-z0-9]/gi, "");
      const row = h("label", { class: "check-row", for: id }, [
        h("input", {
          type: "checkbox",
          id,
          checked: state.specificForms.includes(form) ? "checked" : null,
          onchange: (e) => {
            if (e.target.checked) state.specificForms.push(form);
            else state.specificForms = state.specificForms.filter((f) => f !== form);
          },
        }),
        h("span", { class: "row-label" }, form),
      ]);
      formGrid.appendChild(row);
    });
    panel.appendChild(formGrid);
  }

  panel.appendChild(h("h3", {}, "Target Regulatory Market(s)"));
  panel.appendChild(h("p", { class: "field-hint" }, "Schedule M is pre-selected as the home authority. Markets marked “not covered” have no data in this dataset — they'll show as such rather than being silently guessed."));
  const marketGrid = h("div", { class: "market-grid" });
  DATA.authorities.forEach((a) => {
    const id = "mkt-" + a.key;
    const row = h("label", { class: "check-row" + (a.covered ? "" : " uncovered"), for: id }, [
      h("input", {
        type: "checkbox",
        id,
        checked: state.targetMarkets.includes(a.key) ? "checked" : null,
        onchange: (e) => {
          if (e.target.checked) state.targetMarkets.push(a.key);
          else state.targetMarkets = state.targetMarkets.filter((k) => k !== a.key);
        },
      }),
      h("span", {}, [
        h("span", { class: "row-label" }, a.label),
        !a.covered ? h("span", { class: "badge uncovered" }, "not covered") : null,
        a.shared_note ? h("span", { class: "row-meta" }, a.shared_note) : null,
      ]),
    ]);
    marketGrid.appendChild(row);
  });
  panel.appendChild(marketGrid);

  panel.appendChild(h("h3", {}, "Facility Scale"));
  const scaleRow = h("div", { class: "field-row" });
  scaleRow.appendChild(
    h("div", { class: "field-block narrow" }, [
      h("label", {}, "Scale"),
      h(
        "select",
        { onchange: (e) => (state.scaleSize = e.target.value) },
        ["Small", "Medium", "Large"].map((s) => h("option", { value: s, selected: state.scaleSize === s ? "selected" : null }, s))
      ),
    ])
  );
  scaleRow.appendChild(
    h("div", { class: "field-block narrow" }, [
      h("label", {}, "Batch size (kg or units)"),
      h("input", { type: "text", value: state.batchSize, oninput: (e) => (state.batchSize = e.target.value), placeholder: "e.g. 50,000 tablets" }),
    ])
  );
  panel.appendChild(scaleRow);
  panel.appendChild(h("p", { class: "field-hint" }, "No authority prescribes a room-area formula from batch size — this is captured for context only."));

  root.appendChild(panel);
}

// ---------------------------------------------------------------------
// Step 2 — Room / Zone selection
// ---------------------------------------------------------------------

function applicableRooms() {
  if (!state.category) return [];
  return DATA.rooms.filter((r) => r.applies_to[state.category]);
}

function renderStep2() {
  const root = document.getElementById("step-2");
  clear(root);
  const panel = h("div", { class: "panel" });
  panel.appendChild(h("h2", {}, "Step 2 — Rooms & Zones"));
  panel.appendChild(h("p", { class: "field-hint" }, "Select every room/zone you want assessed. Grouped by process stage, filtered to what applies to " + (CATEGORY_DEFS.find((c) => c.key === state.category) || {}).label + "."));

  const rooms = applicableRooms();
  const byStage = {};
  rooms.forEach((r) => {
    byStage[r.process_stage] = byStage[r.process_stage] || [];
    byStage[r.process_stage].push(r);
  });

  Object.keys(byStage).forEach((stage) => {
    const group = h("div", { class: "room-group" });
    group.appendChild(h("h4", {}, stage));
    const list = h("div", { class: "checkbox-list" });
    byStage[stage].forEach((r) => {
      const id = "room-" + r.id;
      list.appendChild(
        h("label", { class: "check-row", for: id }, [
          h("input", {
            type: "checkbox",
            id,
            checked: state.selectedRooms.includes(r.id) ? "checked" : null,
            onchange: (e) => {
              if (e.target.checked) state.selectedRooms.push(r.id);
              else state.selectedRooms = state.selectedRooms.filter((x) => x !== r.id);
            },
          }),
          h("span", {}, [h("span", { class: "row-label" }, r.name), h("span", { class: "row-meta" }, r.typical_grade)]),
        ])
      );
    });
    group.appendChild(list);
    panel.appendChild(group);
  });

  if (!rooms.length) panel.appendChild(h("p", { class: "empty-hint" }, "No rooms found for this category — go back and pick a dosage form category first."));

  root.appendChild(panel);
}

// ---------------------------------------------------------------------
// Step 3 — Parameter input
// ---------------------------------------------------------------------

function relevantParams() {
  return DATA.parameters.filter((p) => !NON_SCORED_CATEGORY_EXCLUDE.includes(p.category) && p.applicability[state.category]);
}

function appliesAtNormalized(param) {
  return param.applies_at === "Room" ? "room" : "facility";
}

function resolveInputKind(param) {
  if (param.id === "DFS-003") return "number";
  const dt = (param.data_type || "").toLowerCase();
  if (dt.includes("boolean") && (dt.includes("text") || dt.includes("categorical"))) return "boolean-text";
  if (dt === "boolean") return "boolean";
  if (dt.startsWith("numeric range")) return "number-range";
  if (dt === "numeric") return "number";
  if (dt.includes("categorical")) return "select";
  return "text";
}

function optionsFor(param) {
  if (OPTION_OVERRIDES[param.id]) return OPTION_OVERRIDES[param.id];
  const raw = param.unit_options || "";
  if (raw.includes(" / ")) return raw.split(" / ").map((s) => s.trim());
  return [raw];
}

function renderParamField(param, value, onChange) {
  const kind = resolveInputKind(param);
  const wrap = h("div", { class: "field-block" });
  wrap.appendChild(h("label", {}, param.name));

  if (kind === "number") {
    const unit = param.id === "DFS-003" ? "% RH" : param.unit_options;
    const input = h("input", {
      type: "number",
      step: "any",
      value: value === undefined || value === null ? "" : value,
      placeholder: unit || "",
      oninput: (e) => onChange(e.target.value === "" ? null : parseFloat(e.target.value)),
    });
    wrap.appendChild(input);
    if (unit) wrap.appendChild(h("span", { class: "field-note" }, unit));
  } else if (kind === "number-range") {
    const rowWrap = h("div", { style: "display:flex;gap:8px;align-items:center;" });
    const v = value || {};
    rowWrap.appendChild(
      h("input", {
        type: "number", step: "any", placeholder: "min", value: v.min ?? "",
        oninput: (e) => onChange({ ...v, min: e.target.value === "" ? null : parseFloat(e.target.value) }),
      })
    );
    rowWrap.appendChild(h("span", {}, "–"));
    rowWrap.appendChild(
      h("input", {
        type: "number", step: "any", placeholder: "max", value: v.max ?? "",
        oninput: (e) => onChange({ ...v, max: e.target.value === "" ? null : parseFloat(e.target.value) }),
      })
    );
    wrap.appendChild(rowWrap);
    if (param.unit_options) wrap.appendChild(h("span", { class: "field-note" }, param.unit_options));
  } else if (kind === "select") {
    const opts = optionsFor(param);
    const sel = h(
      "select",
      { onchange: (e) => onChange(e.target.value) },
      [h("option", { value: "" }, "— select —")].concat(opts.map((o) => h("option", { value: o, selected: value === o ? "selected" : null }, o)))
    );
    wrap.appendChild(sel);
  } else if (kind === "boolean") {
    const sel = h(
      "select",
      { onchange: (e) => onChange(e.target.value === "" ? null : e.target.value === "true") },
      [
        h("option", { value: "" }, "— select —"),
        h("option", { value: "true", selected: value === true ? "selected" : null }, "Yes"),
        h("option", { value: "false", selected: value === false ? "selected" : null }, "No"),
      ]
    );
    wrap.appendChild(sel);
  } else if (kind === "boolean-text") {
    const v = value || {};
    const sel = h(
      "select",
      { onchange: (e) => onChange({ ...v, value: e.target.value === "" ? null : e.target.value === "true" }) },
      [
        h("option", { value: "" }, "— select —"),
        h("option", { value: "true", selected: v.value === true ? "selected" : null }, "Yes"),
        h("option", { value: "false", selected: v.value === false ? "selected" : null }, "No"),
      ]
    );
    wrap.appendChild(sel);
    wrap.appendChild(
      h("input", { type: "text", placeholder: "Detail (method / zone rating / etc.)", value: v.text || "", oninput: (e) => onChange({ ...v, text: e.target.value }) })
    );
  } else {
    wrap.appendChild(h("textarea", { oninput: (e) => onChange(e.target.value) }, value || ""));
  }

  if (param.notes) wrap.appendChild(h("span", { class: "field-note" }, param.notes));
  return wrap;
}

function renderStep3() {
  const root = document.getElementById("step-3");
  clear(root);
  const panel = h("div", { class: "panel" });
  panel.appendChild(h("h2", {}, "Step 3 — Facility & Room Parameters"));

  const params = relevantParams();
  const facilityParams = params.filter((p) => appliesAtNormalized(p) === "facility");
  const roomParams = params.filter((p) => appliesAtNormalized(p) === "room");

  if (facilityParams.length) {
    panel.appendChild(h("h3", {}, "Facility-level parameters (entered once)"));
    const grouped = {};
    facilityParams.forEach((p) => {
      grouped[p.category] = grouped[p.category] || [];
      grouped[p.category].push(p);
    });
    Object.keys(grouped).forEach((cat) => {
      const row = h("div", { class: "field-row" });
      grouped[cat].forEach((p) => {
        row.appendChild(
          renderParamField(p, state.facilityValues[p.id], (val) => {
            state.facilityValues[p.id] = val;
          })
        );
      });
      panel.appendChild(row);
    });
  }

  const selectedRooms = state.selectedRooms.map((id) => DATA.roomById[id]).filter(Boolean);
  if (!selectedRooms.length) {
    panel.appendChild(h("p", { class: "empty-hint" }, "No rooms selected — go back to Step 2."));
  }

  selectedRooms.forEach((room) => {
    state.roomValues[room.id] = state.roomValues[room.id] || {};
    const section = h("div", { class: "room-param-section" });
    section.appendChild(h("div", { class: "room-title" }, room.name));
    section.appendChild(h("div", { class: "room-sub" }, `${room.process_stage} · Typical grade: ${room.typical_grade}`));

    if (room.bundled_area_note) {
      section.appendChild(h("p", { class: "field-hint" }, "⚠ " + room.bundled_area_note));
    }

    // Room Net Area (special-cased: per-room Schedule M minimum lives on the room record)
    const areaWrap = h("div", { class: "field-row" });
    areaWrap.appendChild(
      h("div", { class: "field-block" }, [
        h("label", {}, "Room Net Area (m²)"),
        h("input", {
          type: "number", step: "any",
          value: state.roomValues[room.id]["DIM-001"] ?? "",
          oninput: (e) => (state.roomValues[room.id]["DIM-001"] = e.target.value === "" ? null : parseFloat(e.target.value)),
        }),
        h("span", { class: "field-note" }, room.min_area_sqm != null ? `Schedule M minimum: ${room.min_area_sqm} m²` : "Schedule M gives no numeric minimum for this room"),
      ])
    );
    section.appendChild(areaWrap);

    const applicableRoomParams = roomParams.filter((p) => {
      if (p.id === "DIM-001") return false; // rendered as a special-cased field above (tied to room.min_area_sqm)
      const filter = PARAM_ROOM_FILTERS[p.id];
      return filter ? filter(room) : true;
    });

    const grouped = {};
    applicableRoomParams.forEach((p) => {
      grouped[p.category] = grouped[p.category] || [];
      grouped[p.category].push(p);
    });
    Object.keys(grouped).forEach((cat) => {
      const row = h("div", { class: "field-row" });
      grouped[cat].forEach((p) => {
        row.appendChild(
          renderParamField(p, state.roomValues[room.id][p.id], (val) => {
            state.roomValues[room.id][p.id] = val;
          })
        );
      });
      section.appendChild(row);
    });

    panel.appendChild(section);
  });

  root.appendChild(panel);
}

// ---------------------------------------------------------------------
// Rules engine
// ---------------------------------------------------------------------

function resolveContext(paramId, room) {
  if (paramId === "HVAC-002" || paramId === "HVAC-003") {
    return room.grade_tag === "A" || room.grade_tag === "B" ? "sterile_filling" : "non_sterile_manufacturing";
  }
  if (paramId === "HVAC-004") {
    if (room.grade_tag === "B" || room.grade_tag === "A") return "grade_b";
    if (room.grade_tag === "C") return "grade_c";
    if (room.grade_tag === "D") return "grade_d";
    return "non_sterile_production";
  }
  if (paramId === "HVAC-005") {
    return state.category === "sterile" ? "between_adjacent_grades" : "non_sterile";
  }
  if (paramId === "HVAC-009") return "grade_a";
  if (paramId === "LGT-001") {
    if (/Inspection/i.test(room.name)) return "inspection";
    if (["Storage", "Store", "Hold", "Receiving"].includes(room.process_stage)) return "storage";
    if ((room.grade_tag === "A" || room.grade_tag === "B") && room.process_stage === "Filling") return "filling_area";
    return "general_processing";
  }
  return "all";
}

function getThresholdsFor(paramId, room) {
  const ctx = room ? resolveContext(paramId, room) : "all";
  return DATA.thresholds.filter((t) => t.linked_param_id === paramId && (t.context === "all" || t.context === ctx));
}

function authorityDataKey(marketKey) {
  const a = DATA.authorityByKey[marketKey];
  return a ? a.data_key : null;
}

function evaluateNumericOrCategorical(threshold, enteredValue, marketKeys) {
  const perMarket = {};
  const specifiedMarkets = []; // { marketKey, authEntry }

  marketKeys.forEach((mk) => {
    const dataKey = authorityDataKey(mk);
    if (!dataKey) {
      perMarket[mk] = { status: "not_covered" };
      return;
    }
    const authEntry = threshold.authorities[dataKey];
    if (!authEntry || !authEntry.specified) {
      perMarket[mk] = { status: "not_regulated", note: authEntry ? authEntry.note : null };
      return;
    }
    specifiedMarkets.push({ marketKey: mk, authEntry });
  });

  if (enteredValue === null || enteredValue === undefined || enteredValue === "") {
    specifiedMarkets.forEach(({ marketKey }) => (perMarket[marketKey] = { status: "no_value" }));
    return { perMarket, hasValue: false };
  }

  if (threshold.type === "categorical") {
    const hierarchy = threshold.hierarchy;
    const enteredIdx = hierarchy.indexOf(enteredValue);
    specifiedMarkets.forEach(({ marketKey, authEntry }) => {
      const reqIdx = hierarchy.indexOf(authEntry.category);
      const compliant = enteredIdx >= 0 && enteredIdx >= reqIdx;
      perMarket[marketKey] = { status: compliant ? "compliant" : "non_compliant", required: authEntry.category, note: authEntry.note };
    });
  } else {
    const isRange = typeof enteredValue === "object";
    // Guard against JS's null <= N === true coercion: a range bound left blank must not
    // silently read as compliant just because null coerces to 0 in a relational comparison.
    specifiedMarkets.forEach(({ marketKey, authEntry }) => {
      const okMin = authEntry.min == null || (isRange ? enteredValue.min != null && enteredValue.min >= authEntry.min : enteredValue >= authEntry.min);
      const okMax = authEntry.max == null || (isRange ? enteredValue.max != null && enteredValue.max <= authEntry.max : enteredValue <= authEntry.max);
      perMarket[marketKey] = { status: okMin && okMax ? "compliant" : "non_compliant", min: authEntry.min, max: authEntry.max, note: authEntry.note };
    });
  }
  return { perMarket, hasValue: true };
}

function strictestBound(threshold, marketKeys) {
  // Returns { min, max, drivingMin: [marketKeys], drivingMax: [marketKeys] } across specified+selected markets
  let min = null, max = null;
  let drivingMin = [], drivingMax = [];
  marketKeys.forEach((mk) => {
    const dataKey = authorityDataKey(mk);
    if (!dataKey) return;
    const a = threshold.authorities[dataKey];
    if (!a || !a.specified) return;
    if (a.min != null) {
      if (min === null || a.min > min) { min = a.min; drivingMin = [mk]; }
      else if (a.min === min) drivingMin.push(mk);
    }
    if (a.max != null) {
      if (max === null || a.max < max) { max = a.max; drivingMax = [mk]; }
      else if (a.max === max) drivingMax.push(mk);
    }
  });
  return { min, max, drivingMin, drivingMax };
}

function strictestCategory(threshold, marketKeys) {
  let best = null, driving = [];
  marketKeys.forEach((mk) => {
    const dataKey = authorityDataKey(mk);
    if (!dataKey) return;
    const a = threshold.authorities[dataKey];
    if (!a || !a.specified) return;
    const idx = threshold.hierarchy.indexOf(a.category);
    const bestIdx = best === null ? -1 : threshold.hierarchy.indexOf(best);
    if (idx > bestIdx) { best = a.category; driving = [mk]; }
    else if (idx === bestIdx) driving.push(mk);
  });
  return { category: best, driving };
}

function marketLabel(mk) {
  const a = DATA.authorityByKey[mk];
  return a ? a.label : mk;
}

function labelList(keys) {
  return keys.map(marketLabel).join(", ");
}

// ---------------------------------------------------------------------
// Step 4 — Results
// ---------------------------------------------------------------------

function buildEvaluationRows() {
  // Each row: { scope: 'facility'|room object, param, threshold, entered, evalResult }
  const rows = [];
  const params = relevantParams();
  const facilityParams = params.filter((p) => appliesAtNormalized(p) === "facility");
  const roomParams = params.filter((p) => appliesAtNormalized(p) === "room");
  const selectedRooms = state.selectedRooms.map((id) => DATA.roomById[id]).filter(Boolean);

  facilityParams.forEach((p) => {
    const thresholds = getThresholdsFor(p.id, null);
    thresholds.forEach((t) => {
      const entered = state.facilityValues[p.id];
      const evalResult = evaluateNumericOrCategorical(t, entered, state.targetMarkets);
      rows.push({ scope: "facility", room: null, param: p, threshold: t, entered, evalResult });
    });
  });

  selectedRooms.forEach((room) => {
    roomParams.forEach((p) => {
      const filter = PARAM_ROOM_FILTERS[p.id];
      if (filter && !filter(room)) return;
      const thresholds = getThresholdsFor(p.id, room);
      thresholds.forEach((t) => {
        const entered = (state.roomValues[room.id] || {})[p.id];
        const evalResult = evaluateNumericOrCategorical(t, entered, state.targetMarkets);
        rows.push({ scope: "room", room, param: p, threshold: t, entered, evalResult });
      });
    });

    // Room Net Area special-case (Schedule M only — the only sourced number)
    const enteredArea = (state.roomValues[room.id] || {})["DIM-001"];
    if (room.min_area_sqm != null) {
      const perMarket = {};
      state.targetMarkets.forEach((mk) => {
        if (mk === "schedule_m") {
          if (enteredArea === null || enteredArea === undefined || enteredArea === "") perMarket[mk] = { status: "no_value" };
          else perMarket[mk] = { status: enteredArea >= room.min_area_sqm ? "compliant" : "non_compliant", min: room.min_area_sqm };
        } else {
          const dataKey = authorityDataKey(mk);
          perMarket[mk] = dataKey ? { status: "not_regulated", note: "No authority-specific room-area figure in this dataset" } : { status: "not_covered" };
        }
      });
      rows.push({
        scope: "room", room,
        param: { id: "DIM-001-area", name: "Room Net Area", category: "Dimensional", gap_severity: "Significant" },
        threshold: { id: "AREA-" + room.id, type: "numeric", unit: "m²", severity: "Significant", source: "schedule_m_notes", authorities: {} },
        entered: enteredArea, evalResult: { perMarket, hasValue: enteredArea != null },
        areaOverride: { min: room.min_area_sqm, source: room.min_area_source },
      });
    }

    // Cleanroom Grade special-case: no authority-by-authority data exists for this in the
    // source workbook — instead, each room already carries its own expected grade (Room-Zone
    // Master List), synthesized across authorities. Compliant if entered grade >= that room's
    // expected grade, on the Unclassified<D<C<B<A hierarchy. Applies uniformly across whichever
    // markets are selected, since it is not an authority-differentiated check in this dataset.
    const gradeParam = DATA.paramById["HVAC-001"];
    if (gradeParam && gradeParam.applicability[state.category]) {
      const enteredGrade = (state.roomValues[room.id] || {})["HVAC-001"];
      const requiredLabel = GRADE_TAG_TO_LABEL[room.grade_tag] || "Unclassified/CNC";
      const reqIdx = GRADE_HIERARCHY.indexOf(requiredLabel);
      const perMarket = {};
      state.targetMarkets.forEach((mk) => {
        const dataKey = authorityDataKey(mk);
        if (!dataKey) { perMarket[mk] = { status: "not_covered" }; return; }
        if (enteredGrade === null || enteredGrade === undefined || enteredGrade === "") { perMarket[mk] = { status: "no_value" }; return; }
        const enteredIdx = GRADE_HIERARCHY.indexOf(enteredGrade);
        perMarket[mk] = { status: enteredIdx >= reqIdx ? "compliant" : "non_compliant", required: requiredLabel };
      });
      rows.push({
        scope: "room", room,
        param: gradeParam,
        threshold: { id: "GRADE-" + room.id, type: "categorical", hierarchy: GRADE_HIERARCHY, severity: "Significant", source: "room_zone_master_list", authorities: {} },
        entered: enteredGrade, evalResult: { perMarket, hasValue: !!enteredGrade },
        gradeOverride: { required: requiredLabel },
      });
    }
  });

  return rows;
}

function computeMarketRollup(rows) {
  const rollup = {};
  state.targetMarkets.forEach((mk) => {
    const dataKey = authorityDataKey(mk);
    if (!dataKey) { rollup[mk] = "Not Covered by Dataset"; return; }
    let worst = null;
    let anyDefinitive = false;
    rows.forEach((row) => {
      const r = row.evalResult.perMarket[mk];
      if (!r) return;
      if (r.status === "compliant" || r.status === "non_compliant") anyDefinitive = true;
      if (r.status === "non_compliant") {
        const sev = row.threshold.severity || (row.param && row.param.gap_severity) || "Partial";
        const rank = SEVERITY_RANK[sev] ?? 2;
        if (worst === null || rank > worst.rank) worst = { rank, sev };
      }
    });
    if (worst && worst.rank >= 4) rollup[mk] = "Non-Compliant";
    else if (worst) rollup[mk] = "Partial";
    else if (!anyDefinitive) rollup[mk] = "Insufficient Data";
    else rollup[mk] = "Compliant";
  });
  return rollup;
}

function buildRecommendations(rows) {
  const recs = [];
  rows.forEach((row) => {
    const failingMarkets = state.targetMarkets.filter((mk) => {
      const r = row.evalResult.perMarket[mk];
      return r && r.status === "non_compliant";
    });
    if (!failingMarkets.length) return;

    const severity = row.threshold.severity || (row.param && row.param.gap_severity) || "Partial";
    const roomLabel = row.room ? ` in '${row.room.name}'` : "";
    let text;

    if (row.areaOverride) {
      text = `Increase Room Net Area${roomLabel} from ${row.entered} m² to at least ${row.areaOverride.min} m² to satisfy ${row.areaOverride.source}.`;
    } else if (row.gradeOverride) {
      text = `Upgrade Cleanroom Grade${roomLabel} from '${row.entered ?? "not entered"}' to '${row.gradeOverride.required}' — this is this room's designated grade per the Room-Zone Master List.`;
    } else if (row.threshold.type === "categorical") {
      const { category, driving } = strictestCategory(row.threshold, failingMarkets.length ? failingMarkets : state.targetMarkets);
      text = `Upgrade ${row.param.name}${roomLabel} from '${row.entered}' to '${category}' to meet ${labelList(driving)}'s classification requirement.`;
    } else {
      const { min, max, drivingMin, drivingMax } = strictestBound(row.threshold, failingMarkets.length ? failingMarkets : state.targetMarkets);
      const unit = row.threshold.unit || "";
      const enteredDisplay = typeof row.entered === "object" ? `${row.entered.min}–${row.entered.max}` : row.entered;
      if (min != null && max != null) {
        text = `Adjust ${row.param.name}${roomLabel} from ${enteredDisplay} to fall within ${min}–${max} ${unit} to satisfy ${labelList([...new Set([...drivingMin, ...drivingMax])])}.`;
      } else if (min != null) {
        text = `Increase ${row.param.name}${roomLabel} from ${enteredDisplay} to at least ${min} ${unit} to satisfy ${labelList(drivingMin)}.`;
      } else if (max != null) {
        text = `Decrease ${row.param.name}${roomLabel} from ${enteredDisplay} to at most ${max} ${unit} to satisfy ${labelList(drivingMax)}.`;
      } else {
        text = `Review ${row.param.name}${roomLabel} — currently non-compliant with ${labelList(failingMarkets)}.`;
      }
    }
    recs.push({ severity, text, id: row.threshold.id + (row.room ? "-" + row.room.id : "") });
  });

  // Boolean-required checks
  const booleanRows = buildBooleanRows();
  booleanRows.forEach((row) => {
    if (row.status !== "non_compliant") return;
    const roomLabel = row.room ? ` in '${row.room.name}'` : "";
    recs.push({
      severity: row.threshold.severity,
      text: `Add ${row.threshold.parameter_name}${roomLabel} — ${row.threshold.note}`,
      id: row.threshold.id + (row.room ? "-" + row.room.id : ""),
    });
  });

  recs.sort((a, b) => (SEVERITY_RANK[b.severity] ?? 2) - (SEVERITY_RANK[a.severity] ?? 2));
  return recs;
}

function buildBooleanRows() {
  const rows = [];
  const params = relevantParams();
  const facilityParams = params.filter((p) => appliesAtNormalized(p) === "facility");
  const roomParams = params.filter((p) => appliesAtNormalized(p) === "room");
  const selectedRooms = state.selectedRooms.map((id) => DATA.roomById[id]).filter(Boolean);

  DATA.boolean_thresholds.forEach((bt) => {
    const param = DATA.paramById[bt.linked_param_id];
    if (!param || !param.applicability[state.category]) return;
    const atFacility = appliesAtNormalized(param) === "facility";
    if (atFacility) {
      const v = state.facilityValues[param.id];
      const val = typeof v === "object" && v !== null ? v.value : v;
      let status = "no_value";
      if (val === true) status = "compliant";
      else if (val === false) status = "non_compliant";
      rows.push({ room: null, threshold: bt, param, entered: val, status });
    } else {
      selectedRooms.forEach((room) => {
        const filter = PARAM_ROOM_FILTERS[param.id];
        if (filter && !filter(room)) return;
        const v = (state.roomValues[room.id] || {})[param.id];
        const val = typeof v === "object" && v !== null ? v.value : v;
        let status = "no_value";
        if (val === true) status = "compliant";
        else if (val === false) status = "non_compliant";
        rows.push({ room, threshold: bt, param, entered: val, status });
      });
    }
  });
  return rows;
}

function checkStructuralFlags() {
  const active = [];
  DATA.structural_flags.forEach((f) => {
    if (f.trigger.specific_dosage_form_any_of) {
      const hit = f.trigger.specific_dosage_form_any_of.some((form) => state.specificForms.some((sf) => sf.includes(form) || form.includes(sf)));
      if (hit) active.push(f);
    }
    if (f.trigger.facility_development_stage_any_of) {
      if (state.devStage && f.trigger.facility_development_stage_any_of.includes(state.devStage)) active.push(f);
    }
  });
  return active;
}

function statusPillClass(status) {
  return {
    compliant: "status-compliant",
    non_compliant: "status-noncompliant",
    not_regulated: "status-notregulated",
    not_covered: "status-notcovered",
    no_value: "status-na",
  }[status] || "status-na";
}

function statusLabel(status) {
  return {
    compliant: "Compliant",
    non_compliant: "Non-Compliant",
    not_regulated: "Not regulated here",
    not_covered: "Not covered",
    no_value: "No value entered",
  }[status] || status;
}

function severityTagClass(sev) {
  return { Critical: "sev-critical", Significant: "sev-significant", Partial: "sev-partial", Aligned: "sev-aligned" }[sev] || "sev-partial";
}

function renderStep4() {
  const root = document.getElementById("step-4");
  clear(root);

  const rows = buildEvaluationRows();
  const booleanRows = buildBooleanRows();
  const rollup = computeMarketRollup(rows.concat(booleanRows.map((br) => ({ threshold: br.threshold, evalResult: { perMarket: Object.fromEntries(state.targetMarkets.map((mk) => [mk, { status: br.status }])) }, param: br.param }))));
  const recs = buildRecommendations(rows);
  const structural = checkStructuralFlags();

  const panel = h("div", { class: "panel" });
  panel.appendChild(h("h2", {}, "Step 4 — Compliance Results"));

  structural.forEach((f) => {
    panel.appendChild(h("div", { class: "structural-banner" }, [h("strong", {}, "Regulatory vacuum flagged"), f.message]));
  });

  panel.appendChild(h("h3", {}, "Which frameworks does this facility qualify under?"));
  const marketGrid = h("div", { class: "market-summary-grid" });
  state.targetMarkets.forEach((mk) => {
    const status = rollup[mk];
    const cls = { Compliant: "overall-compliant", Partial: "overall-partial", "Non-Compliant": "overall-noncompliant", "Insufficient Data": "overall-insufficient", "Not Covered by Dataset": "overall-notcovered" }[status];
    marketGrid.appendChild(h("div", { class: "market-summary-card " + cls }, [h("div", { class: "market-name" }, marketLabel(mk)), h("div", {}, status)]));
  });
  panel.appendChild(marketGrid);

  panel.appendChild(h("h3", {}, "Recommended Modifications"));
  if (!recs.length) {
    panel.appendChild(h("p", { class: "empty-hint" }, "No non-compliant parameters found among selected markets — either everything entered checks out, or no values have been entered yet."));
  } else {
    recs.forEach((r) => {
      panel.appendChild(
        h("div", { class: "recommendation rec-" + r.severity.toLowerCase() }, [
          h("div", { class: "rec-title" }, [h("span", { class: "severity-tag " + severityTagClass(r.severity) }, r.severity)]),
          h("div", {}, r.text),
        ])
      );
    });
  }

  panel.appendChild(h("h3", {}, "Detailed Parameter Status"));
  const tableScroll = h("div", { class: "table-scroll" });
  const table = h("table", { class: "results-table" });
  const headRow = h("tr", {}, [h("th", {}, "Room"), h("th", {}, "Parameter"), h("th", {}, "Entered"), h("th", {}, "Severity")].concat(state.targetMarkets.map((mk) => h("th", {}, marketLabel(mk)))));
  table.appendChild(h("thead", {}, headRow));
  const tbody = h("tbody");
  rows.forEach((row) => {
    const enteredDisplay = row.entered === null || row.entered === undefined || row.entered === "" ? "—" : typeof row.entered === "object" ? `${row.entered.min ?? "?"}–${row.entered.max ?? "?"}` : String(row.entered);
    const sev = row.threshold.severity || (row.param && row.param.gap_severity) || "Partial";
    const tr = h("tr", {}, [
      h("td", {}, row.room ? row.room.name : "Facility"),
      h("td", {}, row.param.name),
      h("td", {}, enteredDisplay),
      h("td", {}, h("span", { class: "severity-tag " + severityTagClass(sev) }, sev)),
    ]);
    state.targetMarkets.forEach((mk) => {
      const r = row.evalResult.perMarket[mk] || { status: "no_value" };
      const cell = h("td", {}, h("span", { class: "status-pill " + statusPillClass(r.status) }, statusLabel(r.status)));
      if (r.note) cell.appendChild(h("div", { class: "field-note" }, r.note));
      tr.appendChild(cell);
    });
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  tableScroll.appendChild(table);
  panel.appendChild(tableScroll);

  if (booleanRows.length) {
    panel.appendChild(h("h3", {}, "Required-Feature Checklist"));
    const btable = h("table", { class: "results-table" });
    btable.appendChild(h("thead", {}, h("tr", {}, [h("th", {}, "Room"), h("th", {}, "Feature"), h("th", {}, "Entered"), h("th", {}, "Severity"), h("th", {}, "Status")])));
    const btbody = h("tbody");
    booleanRows.forEach((br) => {
      btbody.appendChild(
        h("tr", {}, [
          h("td", {}, br.room ? br.room.name : "Facility"),
          h("td", {}, br.threshold.parameter_name),
          h("td", {}, br.entered === true ? "Yes" : br.entered === false ? "No" : "—"),
          h("td", {}, h("span", { class: "severity-tag " + severityTagClass(br.threshold.severity) }, br.threshold.severity)),
          h("td", {}, h("span", { class: "status-pill " + statusPillClass(br.status) }, statusLabel(br.status))),
        ])
      );
    });
    btable.appendChild(btbody);
    panel.appendChild(h("div", { class: "table-scroll" }, btable));
  }

  const scoredIds = new Set(
    DATA.thresholds.map((t) => t.linked_param_id)
      .concat(DATA.boolean_thresholds.map((b) => b.linked_param_id))
      .concat(["DIM-001", "HVAC-001"])
  );
  const infoParams = relevantParams().filter((p) => !scoredIds.has(p.id));
  if (infoParams.length) {
    panel.appendChild(h("h3", {}, "Captured, Not Auto-Checked (free text / no comparable regulatory value in this dataset)"));
    const selectedRoomsForInfo = state.selectedRooms.map((id) => DATA.roomById[id]).filter(Boolean);
    infoParams.forEach((p) => {
      const renderCard = (label, val) =>
        panel.appendChild(
          h("div", { class: "info-card" }, [
            h("span", { class: "info-label" }, label + ": "),
            h("span", {}, val === null || val === undefined || val === "" ? "(not entered)" : typeof val === "object" ? JSON.stringify(val) : String(val)),
            h("div", { class: "info-note" }, p.notes || ""),
          ])
        );
      if (appliesAtNormalized(p) === "facility") {
        renderCard(p.name, state.facilityValues[p.id]);
      } else {
        selectedRoomsForInfo.forEach((room) => {
          const filter = PARAM_ROOM_FILTERS[p.id];
          if (filter && !filter(room)) return;
          renderCard(`${p.name} (${room.name})`, (state.roomValues[room.id] || {})[p.id]);
        });
      }
    });
  }

  root.appendChild(panel);
}

// ---------------------------------------------------------------------
// Navigation
// ---------------------------------------------------------------------

function updateStepIndicator() {
  document.querySelectorAll("#step-indicator li").forEach((li) => {
    const n = parseInt(li.dataset.step, 10);
    li.classList.toggle("active", n === state.step);
    li.classList.toggle("done", n < state.step);
  });
}

function showStep(n) {
  state.step = n;
  [1, 2, 3, 4].forEach((i) => {
    document.getElementById("step-" + i).hidden = i !== n;
  });
  updateStepIndicator();
  if (n === 1) renderStep1();
  if (n === 2) renderStep2();
  if (n === 3) renderStep3();
  if (n === 4) renderStep4();

  document.getElementById("btn-back").disabled = n === 1;
  document.getElementById("btn-next").hidden = n === 4;
  document.getElementById("btn-restart").hidden = n !== 4;
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function validateStep(n) {
  if (n === 1) {
    if (!state.category) return "Pick a dosage form category first.";
    if (!state.specificForms.length) return "Select at least one specific dosage form.";
    if (!state.targetMarkets.length) return "Select at least one target regulatory market.";
    if (state.category === "osd_rnd_pilot" && !state.devStage) return "Select the facility development stage.";
  }
  if (n === 2) {
    if (!state.selectedRooms.length) return "Select at least one room/zone.";
  }
  return null;
}

function wireNav() {
  document.getElementById("btn-back").addEventListener("click", () => {
    if (state.step > 1) showStep(state.step - 1);
  });
  document.getElementById("btn-next").addEventListener("click", () => {
    const err = validateStep(state.step);
    if (err) { alert(err); return; }
    showStep(Math.min(4, state.step + 1));
  });
  document.getElementById("btn-restart").addEventListener("click", () => {
    Object.assign(state, {
      step: 1, category: null, devStage: null, specificForms: [], targetMarkets: ["schedule_m"],
      scaleSize: "Medium", batchSize: "", selectedRooms: [], facilityValues: {}, roomValues: {},
    });
    showStep(1);
  });
}

// ---------------------------------------------------------------------
// Init
// ---------------------------------------------------------------------

async function init() {
  DATA = await loadData();
  wireNav();
  showStep(1);
}

init();
